from enum import Enum
from typing import Annotated, TypeAlias

from ...core import open_enum_validator


class LoyaltyEventSource(str, Enum):
    """Defines whether the event was generated by the Square Point of Sale."""

    SQUARE = "SQUARE"
    """The event is generated by the Square Point of Sale (POS)."""

    LOYALTY_API = "LOYALTY_API"
    """The event is generated by something other than the Square Point of Sale that used the Loyalty API."""

    __str__ = str.__str__


LoyaltyEventSourceOrStr: TypeAlias = Annotated[LoyaltyEventSource | str, open_enum_validator(LoyaltyEventSource)]
